"""Builds docs/seo/MEDICAL_CLAIMS_SAMPLE.md: the 50 products with the highest real Search Console demand whose public text contains
wording that reads as a medical / therapeutic claim. Detection is a lexicon (screening aid), NOT a legal opinion: every row needs human review.
Usage: python medical-claims-sample.py <imp.json> <products.json>"""
import json, re, sys

imp = json.load(open(sys.argv[1], encoding="utf-8"))
prods = json.load(open(sys.argv[2], encoding="utf-8")) or []

# (pattern, category, why it is risky, proposed neutral replacement)
RULES = [
    (r"\b(soigne|soigner|gu[ée]rit|gu[ée]rir|traite(?:ment)? (?:de|du|des|la|le)|remède)\b", "treatment / cure", "A supplement cannot be presented as treating or curing a condition.", "Remove; describe the ingredient and the label dose instead."),
    (r"\b(diab[èe]te|hypertension|cholest[ée]rol|cancer|arthrose|arthrite|ost[ée]oporose|an[ée]mie|d[ée]pression|alzheimer|infertilit[ée]|migraine)\b", "named disease", "Names a disease the product is implied to act on.", "Remove the disease; keep only neutral composition facts."),
    (r"\b(anti-?inflammatoire|anti-?douleur|antibact[ée]rien|antiviral|antifongique|antid[ée]presseur|anxiolytique)\b", "drug-like property", "Pharmacological property reserved to medicines.", "Remove; describe ingredients only."),
    (r"\b(r[ée]duit|r[ée]duire|combat|lutte contre|pr[ée]vient|pr[ée]venir|prot[èe]ge (?:contre|du|des))\b[^.]{0,60}\b(stress|fatigue|douleur|inflammation|vieillissement|maladies?|infections?|cholest[ée]rol)", "risk-reduction / prevention", "Prevention or reduction claims need an authorised health claim.", "Remove or replace with the ingredient's label facts."),
    (r"\b(r[ée]gule|[ée]quilibre|optimise|r[ée]g[ée]n[èe]re|r[ée]pare)\b[^.]{0,50}\b(hormon|cortisol|testost|sommeil|immun|m[ée]tabolisme|flore|glyc[ée]mie|tension)", "physiological claim", "Claims an effect on a body function without an authorised claim.", "Remove; state composition and dosage per label."),
    (r"\b(booste|stimule|renforce|am[ée]liore|favorise)\b[^.]{0,40}\b(syst[èe]me immunitaire|d[ée]fenses|immunit[ée]|testost[ée]rone|libido|fertilit[ée]|m[ée]moire|concentration|sommeil|digestion)", "health-benefit claim", "Benefit wording on health functions needs an authorised claim.", "Remove or soften to neutral usage information."),
    (r"\b(perte de poids|br[ûu]le[- ]graisses?|br[ûu]ler (?:les )?graisses|amaigri|d[ée]tox)", "weight-loss / detox", "Weight-loss and detox promises are high-risk.", "Remove; describe the formula only."),
    (r"\b(cliniquement prouv|scientifiquement prouv|prouv[ée]e? (?:cliniquement|scientifiquement)|100\s*%\s*efficace|r[ée]sultats? garantis?)", "proof / guarantee", "Proof or guarantee wording with no cited evidence.", "Remove unless a verifiable reference is attached."),
]
COMPILED = [(re.compile(p, re.I), c, w, r) for p, c, w, r in RULES]
RESTRICTED = re.compile(r"mk-?677|ibutamoren|sarms?|ostarine|ligandrol|cardarine|dhea|tribulus|booster.?hormon|testo", re.I)


def snippet(text, m, n=70):
    a = max(0, m.start() - n); b = min(len(text), m.end() + n)
    return ("…" if a else "") + re.sub(r"\s+", " ", text[a:b]).strip() + ("…" if b < len(text) else "")


rows = []
for p in prods:
    text = " ".join(filter(None, [p.get("benefit"), p.get("description"), p.get("usage")]))
    hits = []
    for rx, cat, why, fix in COMPILED:
        m = rx.search(text)
        if m:
            hits.append((cat, snippet(text, m), why, fix))
    if not hits:
        continue
    i = imp.get(p["slug"], [0, 0, 0])
    restricted = bool(RESTRICTED.search(p["name"] + " " + p["slug"]))
    rows.append(dict(slug=p["slug"], name=p["name"], imp=i[0], clk=i[1], pos=i[2], indexable=p["indexable"], instock=p["instock"], hits=hits, restricted=restricted))

rows.sort(key=lambda r: (-r["imp"], -r["clk"]))
top = rows[:50]
out = ["# Medical-claim review sample — 50 highest-demand products", "",
       "Generated by `ops/seo/medical-claims-sample.py` from Search Console impressions (90 days to 2026-11-13) joined with the live catalogue text.",
       f"Products with demand AND flagged wording: **{len(rows)}** (of {len(prods)} product pages with impressions). Detection is a lexicon used as a screening aid: **every row needs human review**; nothing here was changed in the catalogue.", "",
       "Legend: *Evidence available* = none attached in the catalogue (no study, authorised claim or label reference is stored), so every claim below is treated as unsupported until a source is provided. *Human review* is always required for health wording. *Keep noindex* applies to restricted/hormone-type items and to any page where the claim cannot be softened.", "",
       "| # | Product | Impr. | Clicks | Index | Stock | Flagged wording (excerpt) | Type | Proposed correction | Keep noindex? |", "|---|---|---:|---:|---|---|---|---|---|---|"]
for n, r in enumerate(top, 1):
    cats = "; ".join(sorted({h[0] for h in r["hits"]}))
    ex = h = r["hits"][0][1].replace("|", "/")
    fix = r["hits"][0][3]
    noidx = "YES (restricted/hormone-type)" if r["restricted"] else ("Only if claim cannot be softened" if r["indexable"] else "Already noindex")
    out.append(f"| {n} | [{r['name'][:60]}](https://paratunisie.com/produits/{r['slug']}) | {r['imp']} | {r['clk']} | {'yes' if r['indexable'] else 'no'} | {'yes' if r['instock'] else 'no'} | « {ex[:170]} » | {cats} | {fix} | {noidx} |")
out += ["", "## Next step", "Review the top 10 with the owner or a pharmacist: for each, either attach an official source (authorised health claim / label) or replace the wording with the neutral correction above. Apply with a dry-run, backup table and rollback, as for all content waves. Do not publish medical claims or index restricted products automatically."]
open("docs/seo/MEDICAL_CLAIMS_SAMPLE.md", "w", encoding="utf-8").write("\n".join(out) + "\n")
print(len(rows), "flagged with demand;", len(top), "in sample;", sum(1 for r in top if r["restricted"]), "restricted-type")
